def roman(n: int) -> str:
    if n == 0:
        return ''

    # Define the mapping of numbers to their corresponding symbols.
    num_to_symbol = {
        1000: "M", 900: "CM", 500: "D", 400: "CD",
        100: "C", 90: "XC", 50: "L", 40: "XL",
        10: "X", 9: "IX", 5: "V", 4: "IV", 1: "I"
    }

    result = ""
    for value, symbol in sorted(num_to_symbol.items(), reverse=True):
        while n >= value:
            result += symbol
            n -= value

    return result

